function pFilteredWork(){return [...state.initiatives.map(i=>({...i,kind:'project',teamId:i.teamId||pSourceTeam(i)})),...pEnsure().tasks.map(t=>({...t,kind:'task'}))].filter(i=>pMatches(i.title+' '+i.owner+' '+pGoalTitle(pGoal(i.objectiveId)))&&pWithin(i.teamId,pFilter.unit)&&(pFilter.status==='all'||i.status===pFilter.status)&&(pFilter.owner==='all'||i.owner===pFilter.owner));}
function pProjects(pid){if(pid){const i=state.initiatives.find(i=>i.id===pid);if(!i)return pMissing();const tasks=pEnsure().tasks.filter(t=>t.projectId===pid);return pHead(i.title,pGoalTitle(pGoal(i.objectiveId)),pButton(txt('ویرایش پروژه','Edit project'),'project-edit',pid,true)+pButton(txt('افزودن وظیفه','Add task'),'task-project',pid))+'<div class="p-card"><div class="p-card-head">'+pOwner(i.owner)+pStatus(i.status)+'</div><div class="p-actions">'+pUnitLink(i.teamId||pSourceTeam(i))+pAnchor(pGoalTitle(pGoal(i.objectiveId)),'#goals/'+(i.objectiveId||''),'p-link')+(i.krId?pAnchor(txt('نتیجه کلیدی مرتبط','Linked key result'),'#results/'+i.krId,'p-link'):'')+'</div><p>'+txt('موعد: ','Due: ')+pDate(i.due)+'</p><div class="p-doc">'+esc(i.description||i.note||'')+'</div><div class="p-note">'+txt('تکمیل پروژه و وظایف، پیشرفت KR را خودکار تغییر نمی‌دهد؛ نتیجه باید جداگانه اندازه‌گیری شود.','Completing projects and tasks does not automatically update KR progress; outcomes must be measured separately.')+'</div></div><div class="p-section"><h2>'+txt('وظایف پروژه','Project tasks')+'</h2></div>'+pTaskRows(tasks)+(i.documentId?pAnchor(txt('مشاهده طرح منبع','View source plan'),'#resources/'+i.documentId):'');}
 const items=pFilteredWork();let groups=new Map();for(const i of items){const key=pFilter.group==='none'?'all':pFilter.group==='unit'?i.teamId||'company':i.objectiveId||'unlinked';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(i);}return pHead(txt('پروژه‌ها و وظایف','Projects & tasks'),txt('کارها را بر اساس هدف یا واحد گروه‌بندی کنید؛ مسئول، وضعیت و موعد هر کار را پیگیری کنید.','Group work by goal or department and track ownership, status and due dates.'),pButton(txt('افزودن پروژه','Add project'),'project',pFilter.unit,true)+pButton(txt('افزودن Task','Add task'),'task',pFilter.unit)+pButton(txt('خروجی CSV','Export CSV'),'export-work'))+pToolbar({status:true,group:true})+(items.length?[...groups].map(([key,rows])=>'<details class="p-group" open><summary>'+esc(key==='all'?txt('همه کارها','All work'):pFilter.group==='unit'?pUnitLabel(key):pGoalTitle(pGoal(key)))+'<span class="p-count">'+pNum(rows.length)+'</span></summary><div>'+pTable([txt('پروژه / وظیفه','Project / task'),txt('مسئول','Owner'),txt('واحد','Unit'),txt('موعد','Due'),txt('وضعیت','Status')],rows.map(i=>[pAnchor(i.title,'#'+(i.kind==='task'?'tasks':'projects')+'/'+i.id,'')+'<small>'+txt(i.kind==='task'?'وظیفه':'پروژه / ابتکار',i.kind==='task'?'Task':'Project / initiative')+'</small>',pOwner(i.owner),pUnitLink(i.teamId),pDate(i.due)+(pOverdue(i)?'<small>'+pTag(txt('معوق','Overdue'),'bad')+'</small>':''),pStatus(i.status)]))+'</div></details>').join(''):pEmpty(txt('کاری در این فیلتر ثبت نشده است','No work in this filter'),pButton(txt('افزودن وظیفه','Add task'),'task',pFilter.unit,true)))+'<div class="p-section"><h2>'+txt('پیشنهادهای لجستیک برای انتخاب و برنامه‌ریزی','Logistics proposals to review and plan')+'</h2>'+pAnchor(txt('بانک کامل ابتکارهای سند','Complete source initiative bank'),'#document/initiatives','p-link')+'</div>'+pSourceProjects(pFilter.unit);}
function pTaskPage(tid){const t=pEnsure().tasks.find(x=>x.id===tid);if(!t)return pMissing();return pHead(t.title,pGoalTitle(pGoal(t.objectiveId)),pButton(txt('ویرایش وظیفه','Edit task'),'task-edit',tid,true)+pButton(t.status==='done'?txt('بازگشایی','Reopen'):txt('تکمیل وظیفه','Complete task'),'task-toggle',tid))+'<div class="p-card"><div class="p-card-head">'+pOwner(t.owner)+pStatus(t.status)+'</div><p>'+pUnitLink(t.teamId)+'</p><p>'+pAnchor(pGoalTitle(pGoal(t.objectiveId)),'#goals/'+(t.objectiveId||''),'p-link')+'</p><p>'+txt('موعد: ','Due: ')+pDate(t.due)+'</p><div class="p-doc">'+esc(t.description||'')+'</div><div class="p-actions">'+(t.projectId?pAnchor(txt('پروژه مرتبط','Related project'),'#projects/'+t.projectId):'')+(t.meetingId?pAnchor(txt('جلسه مرتبط','Related meeting'),'#sessions/'+t.meetingId):'')+'</div></div>';}
function pSourceProjects(uid='all'){const rows=PSOURCEPROJECTS.filter(s=>pWithin(s[3],uid));return rows.length?'<div class="p-grid three">'+rows.map(([sid,a,b,team,doc,goal])=>{const existing=state.initiatives.find(i=>i.logisticsSourceId===sid);return '<article class="p-card"><span class="p-kicker">SOURCE PLAN · PROPOSAL</span><h3>'+txt(a,b)+'</h3><p class="p-caption">'+pUnitLabel(team)+'</p><div class="p-actions">'+pAnchor(txt('متن طرح','Read plan'),'#resources/'+doc,'p-link')+(existing?pAnchor(txt('پروژه افزوده‌شده','Added project'),'#projects/'+existing.id):pButton(txt('افزودن به برنامه','Add to plan'),'adopt-logistics',sid))+'</div><small class="p-muted">'+txt('ارتباط با هدف پیشنهادی است؛ مسئول، بودجه و موعد نیازمند تعیین‌اند.','Goal alignment is proposed; ownership, budget and deadline need confirmation.')+'</small></article>';}).join('')+'</div>':pEmpty(txt('طرح لجستیک مستقیمی برای این واحد ثبت نشده است','No direct logistics proposal for this unit'));}
function pSessionRows(rows){return rows.length?rows.map(m=>'<a class="p-row" href="#sessions/'+m.id+'"><span class="p-row-main"><b>'+esc(m.title||m.person||txt('جلسه','Meeting'))+'</b><small>'+pDate(m.date)+' · '+pUnitLabel(m.teamId)+'</small></span>'+pTag(m.type==='review'?'Review':m.type==='team'?txt('جلسه واحد','Team review'):'1:1')+'</a>').join(''):pEmpty(txt('جلسه‌ای ثبت نشده است','No meetings recorded'));}
function pSessions(mid){if(!mid)return pHead(txt('جلسات و پیگیری','Meetings & follow-through'),txt('گفت‌وگوی ۱:۱، مرور واحد و مرور راهبرد را به هدف و اقدام بعد متصل کنید.','Connect 1:1s, department reviews and strategy reviews to goals and next actions.'),pButton(txt('ثبت جلسه','New meeting'),'meeting',pFilter.unit,true))+pToolbar()+pSessionRows(state.meetings.filter(m=>pWithin(m.teamId,pFilter.unit)&&pMatches((m.title||m.person||'')+' '+m.note)));
 const m=state.meetings.find(x=>x.id===mid);if(!m)return pMissing();const tasks=pEnsure().tasks.filter(t=>t.meetingId===mid);return pHead(m.title||m.person||txt('جلسه','Meeting'),pDate(m.date)+' · '+pUnitLabel(m.teamId),pButton(txt('ویرایش جلسه','Edit meeting'),'meeting-edit',mid,true)+pButton(txt('افزودن اقدام پیگیری','Add follow-up task'),'task-meeting',mid))+'<div class="p-grid two"><section class="p-card"><h2>'+txt('دستور جلسه و Talking points','Talking points')+'</h2><div class="p-doc">'+esc(m.points||txt('ثبت نشده است','Not recorded'))+'</div><p>'+esc(m.participants||m.person||'')+'</p><div class="p-actions">'+pUnitLink(m.teamId)+(m.objectiveId?pAnchor(pGoalTitle(pGoal(m.objectiveId)),'#goals/'+m.objectiveId,'p-link'):'')+'</div></section><section class="p-card"><h2>'+txt('یادداشت و تصمیم‌ها','Notes & decisions')+'</h2><div class="p-doc">'+esc(m.note||'')+'</div><h3>'+txt('اقدام بعد','Next actions')+'</h3><div class="p-doc">'+esc(m.next||'')+'</div></section></div><div class="p-section"><h2>'+txt('وظایف متصل به جلسه','Tasks linked to this meeting')+'</h2></div>'+pTaskRows(tasks);}
function pToday(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tehran',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
function pOverdue(x){return !!x.due&&String(x.due).slice(0,10)<pToday()&&!['done','closed'].includes(x.status);}
function pMetrics(uid='all'){
 const teams=state.teams.filter(t=>pWithin(t.id,uid)),p=pEnsure(),goals=uid==='all'?allObjectives():pUnitGoals(uid),krs=goals.flatMap(x=>x.objective.krs||[]),known=krs.filter(pKrKnown),work=[...state.initiatives.map(i=>({...i,teamId:i.teamId||pSourceTeam(i)})),...p.tasks].filter(i=>pWithin(i.teamId,uid));
 const withOwner=teams.filter(t=>t.lead?.trim()||p.unitProfiles[t.id]?.owner?.trim()),revised=teams.filter(t=>['submitted','approved'].includes(p.unitProfiles[t.id]?.revisionStatus)),rollout=teams.filter(t=>p.unitProfiles[t.id]?.rolloutStatus==='active'),active=teams.filter(t=>p.unitProfiles[t.id]?.rolloutStatus==='active'||t.okrs?.some(o=>o.status==='active')),kpiCovered=teams.filter(t=>pKpis().some(k=>k.teamId===t.id));
 return {teams,goals,krs,measured:known.length,progress:known.length?Math.round(known.reduce((s,k)=>s+progress(k),0)/known.length):null,withOwner:withOwner.length,revised:revised.length,rollout:rollout.length,active:active.length,kpiCovered:kpiCovered.length,delayed:work.filter(pOverdue).length,work};
}
function pTrend(records,unit=''){
 const points=records.filter(v=>v.at&&Number.isFinite(v.value)).sort((a,b)=>String(a.at).localeCompare(String(b.at))).slice(-18);
 if(!points.length)return pEmpty(txt('برای نمایش روند، حداقل یک مقدار تاریخ‌دار ثبت کنید','Record a dated value to see the trend'));
 const min=Math.min(...points.map(p=>p.value)),max=Math.max(...points.map(p=>p.value)),range=max-min||Math.max(1,Math.abs(max)*.1),y=v=>160-(v-min)/range*115,x=i=>50+(points.length===1?230:i/(points.length-1)*450);
 const line=points.map((v,i)=>x(i)+','+y(v.value)).join(' '),name=txt('روند مقادیر ثبت‌شده','Recorded value trend');
 return '<figure style="margin:0"><svg class="p-chart" viewBox="0 0 550 215" role="img" aria-label="'+name+'"><title>'+name+'</title><path d="M50 30 V165 H510" fill="none" stroke="#d9e3eb"/><text x="8" y="45">'+esc(pNum(max))+'</text><text x="8" y="164">'+esc(pNum(min))+'</text><polyline points="'+line+'" fill="none" stroke="#239c9e" stroke-width="2.5"/>'+points.map((v,i)=>'<circle cx="'+x(i)+'" cy="'+y(v.value)+'" r="4" fill="#239c9e"><title>'+esc(pDate(v.at)+' · '+v.value+' '+unit)+'</title></circle>'+(i===0||i===points.length-1||points.length<5?'<text x="'+x(i)+'" y="192" text-anchor="middle">'+esc(pDate(v.at))+'</text>':'')).join('')+'</svg><figcaption>'+txt('فقط داده‌های ثبت‌شده؛ فاصله نقاط بر اساس ترتیب ثبت است.','Recorded data only; points are spaced by recording order.')+' '+esc(unit)+'</figcaption></figure>';
}
function pGoalTrend(o){const records=state.history.filter(h=>(o.krs||[]).some(k=>k.id===h.krId)).sort((a,b)=>String(a.at).localeCompare(String(b.at))),values=new Map(),out=[];for(const h of records){values.set(h.krId,h.current);const known=(o.krs||[]).filter(k=>values.has(k.id)&&pKrKnown({...k,current:values.get(k.id)}));if(known.length)out.push({at:h.at,value:Math.round(known.reduce((s,k)=>s+progress({...k,current:values.get(k.id)}),0)/known.length)});}return pTrend(out,'%')+'<small class="p-muted">'+txt('محاسبه با مبنا و هدف فعلی؛ تغییر تعریف شاخص می‌تواند تفسیر روند را تغییر دهد.','Computed using current baselines and targets; definition changes may affect trend interpretation.')+'</small>';}
function pCoverage(n,d){return '<b>'+pNum(n)+' / '+pNum(d)+'</b>'+pProgress(d?n/d*100:0);}
function pAnalytics(report=false){const m=pMetrics(pFilter.unit),p=pEnsure(),records=state.history.slice().sort((a,b)=>String(a.at).localeCompare(String(b.at))),byGoal=allObjectives().map(x=>x.objective),latest=new Map(),trend=[];for(const h of records){latest.set(h.krId,h.current);const krs=m.krs.filter(k=>latest.has(k.id)&&pKrKnown({...k,current:latest.get(k.id)}));if(krs.length)trend.push({at:h.at,value:Math.round(krs.reduce((s,k)=>s+progress({...k,current:latest.get(k.id)}),0)/krs.length)});}
 const title=report?txt('گزارش مدیریتی اجرا','Execution management report'):txt('داشبورد اجرای راهبرد','Strategy execution dashboards');
 let html=pHead(title,txt('پوشش و پیشرفت از اطلاعات ثبت‌شده محاسبه می‌شوند؛ داده ناموجود با صفر عملکرد برابر نیست.','Coverage and progress use recorded data; missing data is not treated as zero performance.'),pButton(txt('خروجی CSV','Export CSV'),'export-report')+pButton(txt('چاپ / PDF','Print / PDF'),'print')+pButton(txt('پشتیبان JSON','Export JSON'),'export-json'))+pToolbar({unit:true})+'<div class="p-grid four">'+pStat(m.progress,txt('میانگین KRهای دارای داده، درصد','Measured KR average, %'),'#goals',pNum(m.measured)+' / '+pNum(m.krs.length)+' KR')+pStat(m.goals.length,txt('شمار اهداف','Objective count'),'#goals')+pStat(m.active,txt('واحدهای فعال','Active units'),'#organization')+pStat(m.delayed,txt('کارهای معوق','Overdue work'),'#projects')+'</div><div class="p-grid two" style="margin-top:18px"><section class="p-card"><h2>'+txt('پوشش واحدهای سازمانی','Organizational unit coverage')+'</h2>'+[[m.revised,txt('بازنگری: ارسال یا تأیید','Revision: submitted / approved')],[m.rollout,txt('استقرار: فعال','Rollout: active')],[m.kpiCovered,txt('KPI با مالکیت صریح واحد','Explicit unit KPI ownership')],[m.withOwner,txt('واحد دارای مسئول','Units with assigned owners')]].map(([n,l])=>'<div class="p-meter"><span>'+l+'</span><span>'+pNum(n)+' / '+pNum(m.teams.length)+'</span>'+pProgress(m.teams.length?n/m.teams.length*100:0)+'</div>').join('')+'<div class="p-note">'+txt('واحد فعال: استقرار فعال یا حداقل یک OKR فعالِ خود واحد. KPI coverage: واحدی که KPI صریحاً به آن تخصیص دارد. مخرج، تعداد واحدهای محدوده انتخاب‌شده است.','Active unit: active rollout or at least one own active OKR. KPI coverage: a KPI explicitly assigned to the unit. Denominator: all units in the selected scope.')+'</div></section><section class="p-card"><h2>'+txt('روند پیشرفت ثبت‌شده OKR','Recorded OKR progress trend')+'</h2>'+pTrend(trend,'%')+'<small class="p-muted">'+txt('بر اساس Check-inها و مبنا و هدف فعلی؛ در هر نقطه فقط KRهای اندازه‌گیری‌شده تا آن زمان وارد میانگین می‌شوند.','Based on check-ins and current baselines / targets. Each point averages only KRs measured by that time.')+'</small></section></div><div class="p-section"><h2>'+txt('گزارش پوشش واحدها','Unit coverage report')+'</h2>'+pAnchor(txt('بازنگری و استقرار','Revision & rollout'),'#revision','p-link')+'</div>'+pTable([txt('واحد','Unit'),txt('مسئول','Owner'),txt('اهداف خود واحد','Own OKRs'),txt('بازنگری','Revision'),txt('استقرار','Rollout'),txt('کار معوق','Overdue')],m.teams.map(t=>{const u=p.unitProfiles[t.id]||{};return [pUnitLink(t.id),pOwner(t.lead||u.owner),pNum(t.okrs?.length||0),pStatus(u.revisionStatus||'not-started'),pStatus(u.rolloutStatus||'not-started'),pNum(m.work.filter(i=>i.teamId===t.id&&pOverdue(i)).length)];}));
 if(report)html+='<div class="p-section"><h2>'+txt('کارهای نیازمند پیگیری','Items needing follow-through')+'</h2></div>'+pTaskRows(p.tasks.filter(t=>pWithin(t.teamId,pFilter.unit)&&pOverdue(t)))+'<div class="p-section"><h2>'+txt('آخرین ثبت‌های پیشرفت','Recent check-ins')+'</h2></div>'+pTable([txt('نتیجه کلیدی','KR'),txt('تاریخ','Date'),txt('مقدار','Value'),txt('شواهد','Evidence')],records.filter(h=>m.krs.some(k=>k.id===h.krId)).slice(-12).reverse().map(h=>[pAnchor(m.krs.find(k=>k.id===h.krId)?.text||h.krId,'#results/'+h.krId,''),pDate(h.at),esc(h.current),esc(h.note||'')]));return html;}
function pRevisionCard(uid){const p=pEnsure().unitProfiles[uid]||{};return '<section class="p-card"><span class="p-kicker">STRATEGY REVISION & OKR ROLLOUT</span><h2>'+pUnitLabel(uid)+'</h2><div class="p-row"><b>'+txt('مشارکت در بازنگری سند','Strategy revision participation')+'</b>'+pStatus(p.revisionStatus||'not-started')+'</div><div class="p-row"><b>'+txt('وضعیت استقرار OKR','OKR rollout status')+'</b>'+pStatus(p.rolloutStatus||'not-started')+'</div><div class="p-doc">'+esc(p.revisionNote||'')+'</div><p>'+txt('آخرین ثبت: ','Last update: ')+pDate(p.updatedAt)+'</p><div class="p-actions">'+pButton(txt('به‌روزرسانی وضعیت و شواهد','Update status & evidence'),'unit',uid,true)+pAnchor(txt('هشت گام استقرار Perdoo','Perdoo eight-step rollout'),'#roadmap')+'</div></section>';}
function pRevision(){return pHead(txt('بازنگری سند و استقرار OKR','Strategy revision & OKR rollout'),txt('پیشرفت هر واحد را با وضعیت مشخص و یادداشت شواهد ثبت کنید.','Record each unit’s status and supporting evidence.'))+pToolbar()+pTable([txt('واحد','Unit'),txt('مسئول','Owner'),txt('بازنگری سند','Strategy revision'),txt('استقرار OKR','OKR rollout'),txt('به‌روزرسانی','Update')],state.teams.filter(t=>pWithin(t.id,pFilter.unit)&&pMatches(t.name)).map(t=>{const u=pEnsure().unitProfiles[t.id]||{};return [pUnitLink(t.id),pOwner(t.lead),pStatus(u.revisionStatus||'not-started'),pStatus(u.rolloutStatus||'not-started'),pButton(txt('ثبت وضعیت','Set status'),'unit',t.id)];}));}
function pResourceCards(uid='all'){const ids=pDescendants(uid),docs=LOGISTICS_SOURCES.filter(d=>uid==='all'||uid==='company'||ids.has(d.teamId)||uid===d.teamId||pWithin(uid,d.teamId));return '<div class="p-grid two"><a class="p-card clickable" href="#document/foundation"><span class="p-kicker">STRATEGY · 1404</span><h3>'+txt('سند راهبردی تحول و پیشرفت','Strategic Transformation & Progress')+'</h3><p class="p-caption">'+txt('۳۶۶ صفحه · ۱۳ هدف · ۵۳ KR · مرجع کامل درون اپ','366 pages · 13 objectives · 53 KRs · Full in-app reference')+'</p></a><a class="p-card clickable" href="#resources/org-chart"><span class="p-kicker">ORGANIZATION · SOURCE CHART</span><h3>'+txt('چارت سازمانی شرکت','Company organization chart')+'</h3><p class="p-caption">'+txt('بارگذاری با عنوان مهر ۱۴۰۴؛ اصلاحات چاپ‌شده خرداد ۱۴۰۴.','Uploaded as Mehr 1404; printed amendment: Khordad 1404.')+'</p></a>'+docs.map(d=>'<a class="p-card clickable" href="#resources/'+d.id+'"><span class="p-kicker">LOGISTICS · SOURCE PLAN</span><h3>'+txt(d.title,d.titleEn)+'</h3><p class="p-caption">'+txt(d.summary,d.summaryEn)+'</p>'+pTag(txt('محتوای طرح؛ تصویب نهایی تأیید نشده','Plan content; final approval unverified'),'source')+'</a>').join('')+'</div>';}
function pResources(rid){if(!rid)return pHead(txt('اسناد و مراجع پشتیبان','Supporting documents & references'),txt('سند راهبردی، چارت و طرح‌های لجستیک با ارجاع روشن و ارتباط به واحدها.','Strategy, organization chart and logistics plans with clear references and department links.'))+pResourceCards();if(rid==='org-chart')return pHead(txt('مرجع ساختار سازمانی','Organization structure reference'),txt('۶۵ واحد بر اساس چارت اسکن‌شده، صفحات ۲ تا ۱۰؛ نام اشخاص از روی چارت حدس زده نشده است.','65 units from the scanned chart, pages 2–10; people are not inferred from the chart.'))+'<div class="p-note">'+txt('در سطح مستقیم شرکت فقط معاونت مالی، اداری و پشتیبانی و معاونت اقتصادی و فنی قرار دارند؛ معاونت‌های بنادر و فرودگاه‌ها در زیر اداره کل مربوط‌اند.','Only Finance, Administration & Support and Economic & Technical are direct company deputies. Port and airport deputies report to the corresponding directorate.')+'</div>'+pTable([txt('عنوان واحد','Unit'),txt('واحد بالادست','Parent'),txt('سطح','Level'),txt('صفحه منبع','Source page')],ORG_CHART.map(n=>[pUnitLink(n.id),n.parentId?pUnitLink(n.parentId):txt('مدیرعامل','CEO'),txt(...ORG_LEVELS[n.level]),pNum(n.page)]));const d=LOGISTICS_SOURCES.find(d=>d.id===rid);if(!d)return pMissing();return pHead(txt(d.title,d.titleEn),txt(d.summary,d.summaryEn),pAnchor(txt('واحد مرتبط','Related unit'),'#organization/'+d.teamId))+'<div class="p-card"><div class="p-tags">'+pTag(d.filename,'source')+pTag(txt('مرجع طرح؛ به معنی تصویب اجرا نیست','Source plan; does not certify execution approval'),'warn')+'</div><div class="p-note">'+txt('نمای متنی استخراج‌شده از فایل ارسالی؛ تصاویر و آرایش جداول در این نما بازتولید نشده‌اند. ارقام این منابع، داده جاری تأییدشده تلقی نمی‌شوند.','Text extracted from the supplied file; images and original table layouts are not reproduced. Source figures are not treated as verified current data.')+'</div><details open><summary>'+txt('مطالعه متن طرح','Read source plan')+'</summary><div class="p-doc">'+esc(d.text)+'</div></details></div><div class="p-section"><h2>'+txt('تبدیل پیشنهاد به برنامه اجرایی','Turn a proposal into an execution plan')+'</h2></div>'+pSourceProjects(d.teamId);}
function pPeople(uid='all',pid){const people=pEnsure().people;if(pid){const person=people.find(x=>x.id===pid),name=person?.name||pid,aliases=new Set([pid,name,person?.email].filter(Boolean)),goals=allObjectives().filter(x=>aliases.has(x.objective.owner)),tasks=pEnsure().tasks.filter(t=>aliases.has(t.owner)),kpis=pKpis().filter(k=>aliases.has(k.owner));return pHead(name,person?.title||txt('نمای مسئولیت‌ها بر اساس اطلاعات ثبت‌شده','Responsibility view based on recorded assignments'),person?pButton(txt('ویرایش مشخصات','Edit person'),'person-edit',pid,true):pButton(txt('تکمیل مشخصات فرد','Add person record'),'person-prefill',pid,true))+'<div class="p-card">'+pOwner(name)+'<p>'+pUnitLink(person?.teamId)+'</p><p dir="ltr">'+esc(person?.email||'')+'</p><div class="p-note">'+txt('این پرونده مالکیت کار را مشخص می‌کند؛ حساب کاربری یا مجوز امنیتی ایجاد نمی‌کند.','This record identifies work ownership; it does not create an account or grant security permissions.')+'</div></div><div class="p-section"><h2>'+txt('اهداف','Objectives')+'</h2></div>'+pGoalRows(goals)+'<div class="p-section"><h2>'+txt('وظایف','Tasks')+'</h2></div>'+pTaskRows(tasks)+'<div class="p-section"><h2>'+txt('شاخص‌ها','KPIs')+'</h2></div>'+pKpiRows(kpis);}
 const persons=people.filter(p=>pWithin(p.teamId,uid)&&pMatches(p.name+' '+p.email));const owners=new Set([...state.teams.map(t=>t.lead),...allObjectives().map(x=>x.objective.owner),...pKpis().map(k=>k.owner),...pEnsure().tasks.map(t=>t.owner)].filter(Boolean));return '<div class="p-card-head"><h2>'+txt('مسئولان و افراد','People & owners')+'</h2>'+pButton(txt('افزودن فرد','Add person'),'person',uid,true)+'</div>'+(persons.length?'<div class="p-grid three">'+persons.map(p=>'<a class="p-card" href="#people/'+p.id+'"><h3>'+esc(p.name)+'</h3><p class="p-caption">'+esc(p.title||'')+'</p><small>'+pUnitLabel(p.teamId)+'</small></a>').join('')+'</div>':pEmpty(txt('پرونده فردی ثبت نشده است','No people records yet')))+(uid==='all'&&owners.size?'<div class="p-section"><h2>'+txt('نام‌های ثبت‌شده در مسئولیت‌ها','Names recorded in assignments')+'</h2></div><div class="p-tags">'+[...owners].map(name=>pOwner(name)).join('')+'</div>':'');}
