const pPages={map:['نقشه راهبرد','Strategy map'],organization:['سازمان','Organization'],goals:['اهداف و نتایج کلیدی','OKRs'],results:['نتیجه کلیدی','Key result'],kpis:['شاخص‌های کلیدی','KPIs'],projects:['پروژه‌ها و وظایف','Projects & Tasks'],tasks:['جزئیات وظیفه','Task details'],sessions:['جلسات','Meetings'],analytics:['داشبوردها','Dashboards'],reporting:['گزارش‌ها','Reporting'],resources:['اسناد','Documents'],revision:['بازنگری و استقرار','Revision & Rollout'],people:['افراد','People'],search:['جست‌وجو','Search'],source:['ابتکار سند','Source initiative']};
