function pInstallNav(){const box=document.getElementById('platformNav');if(box){box.innerHTML='<div class="nav-label">'+txt('اجرای راهبرد','STRATEGY EXECUTION')+'</div>'+[['start','⌂',txt('میز کار','Workspace')],['organization','▤',txt('ساختار سازمان','Organization')],...PMODULES.map(([k,i,fa,en])=>[k,i,txt(fa,en)]),['revision','↻',txt('بازنگری و استقرار','Revision & Rollout')],['resources','▧',txt('اسناد و مراجع','Documents')],['people','◉',txt('افراد و مسئولان','People & owners')]].map(([key,icon,label])=>'<a href="#'+key+'" '+(location.hash.slice(1).split('/')[0]===key?'class="active" aria-current="page"':'')+'><span class="p-nav-icon">'+icon+'</span><span>'+label+'</span></a>').join('');}const home=document.getElementById('platformHomeQuick');if(home)home.innerHTML='<div class="p-section"><h2>'+txt('ورود مستقیم به ماژول‌ها','Open a module')+'</h2></div><div class="p-grid four">'+pModules()+'</div><div class="p-section"><h2>'+txt('انتخاب حوزه سازمانی','Choose an organization area')+'</h2>'+pAnchor(txt('مشاهده شرکت','Company overview'),'#organization/company','p-link')+'</div><div class="p-grid three">'+pDomainCards()+'</div>';const mobile=document.getElementById('platformMobile');if(mobile){mobile.innerHTML=pOptions([['start',txt('میز کار','Workspace')],['organization',txt('سازمان','Organization')],...PMODULES.map(([k,i,a,b])=>[k,txt(a,b)]),['resources',txt('اسناد','Documents')],['people',txt('افراد','People')]],location.hash.slice(1).split('/')[0]);}}
function pRender(key,record='',tab=''){pEnsure();let body='';if(key==='organization')body=record?pUnitProfile(record,tab||'overview'):pOrgList();if(key==='map')body=pMap(record);if(key==='goals')body=pGoals(record);if(key==='results')body=pResult(record);if(key==='kpis')body=pKpiPage(record);if(key==='projects')body=pProjects(record);if(key==='tasks')body=pTaskPage(record);if(key==='sessions')body=pSessions(record);if(key==='analytics')body=pAnalytics();if(key==='reporting')body=pAnalytics(true);if(key==='resources')body=pResources(record);if(key==='revision')body=pRevision();if(key==='people')body=pHead(txt('افراد و مسئولان','People & owners'),txt('مالکیت هدف، شاخص و کارهای افراد را در یک نمای مرتبط ببینید.','Explore people’s goals, metrics and work ownership.'))+pPeople('all',record);if(key==='search')body=pSearch();if(key==='source')body=pSourceInitiative(record);document.getElementById('platformBody').innerHTML='<div class="p-page">'+body+'<footer class="p-footer">KISH PORTS & AIRPORTS · '+PLATFORM_RELEASE+' · '+txt('ذخیره مستقل در مرورگر','Independent browser workspace')+'</footer></div>';pInstallNav();}
