route=function(){if(!cloudReady)return;let parts;try{parts=decodeURIComponent(location.hash.slice(1)).split('/');}catch{parts=[];}const [key,record,tab]=parts;document.body.classList.toggle('platform-active',!!pPages[key]||key==='start');if(pPages[key]){document.getElementById('authScreen').classList.add('hidden');document.getElementById('authScreen').inert=true;document.getElementById('trainingScreen').classList.remove('show');document.getElementById('executionApp').inert=false;document.body.style.overflow='';document.getElementById('sidebar').classList.remove('open');document.getElementById('actionMenu').classList.remove('open');document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));document.getElementById('view-platform').classList.add('active');pRender(key,record,tab);navigationRecord(location.hash);return;}pBaseRoute();pInstallNav();};
applyLanguage=function(){pBaseLanguage();pInstallNav();if(document.getElementById('view-platform')?.classList.contains('active')){let ps;try{ps=decodeURIComponent(location.hash.slice(1)).split('/');}catch{return;}if(pPages[ps[0]])pRender(...ps);}else if(location.hash==='#start'&&cloudReady)renderStart();};
initializePractice=function(){pEnsure();pBaseInitialize();pInstallNav();};
const pBaseParent=navigationParent;navigationParent=function(hash){const [key,record,tab]=hash.slice(1).split('/');if(key==='organization'&&record){if(tab&&tab!=='overview')return '#organization/'+record;const n=orgNode(pTeam(record)?.orgChartId);return n?.parentId?'#organization/'+n.parentId:record==='company'?'#organization':'#organization/company';}if(pPages[key]&&record)return key==='results'?'#goals/'+(allKrs().find(x=>x.kr.id===record)?.objective.id||''):'#'+key;if(pPages[key])return '#start';return pBaseParent(hash);};
document.addEventListener('submit',e=>{const search=e.target.closest('[data-p-global-search]');if(search){e.preventDefault();const f=new FormData(search);pFilter.q=String(f.get('query')||'').trim();navigateSection('#search');return;}const form=e.target.closest('[data-platform-form]');if(!form)return;e.preventDefault();if(!cloudReady||!pModalContext)return;const c=pModalContext;try{const result=pSubmit(c.kind,Object.fromEntries(new FormData(form)),c.recordId,c.context);if(result.ok){document.getElementById('platformDialog').close();pModalContext=null;navigateSection(result.href||location.hash);}}catch(error){document.getElementById('p-form-error').textContent=error.message;}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-p-action]');if(!b)return;const a=b.dataset.pAction,r=b.dataset.pId||'';if(a==='close-dialog'){document.getElementById('platformDialog').close();return;}if(a==='reset'){pFilter={q:'',unit:'all',status:'all',group:'goal',level:'all',owner:'all'};route();return;}if(a==='export-work'){pExportWork();return;}if(a==='export-report'){pExportReport();return;}if(a==='export-json'){exportData();return;}if(a==='print'){window.print();return;}if(a==='adopt-logistics'){pAdopt(r);return;}if(a==='adopt-source'){adoptSourceInitiative(r).then(()=>{const i=state.initiatives.find(x=>x.sourceId===r);if(i)navigateSection('#projects/'+i.id);});return;}if(a==='task-toggle'){const t=pEnsure().tasks.find(t=>t.id===r);if(t){t.status=t.status==='done'?'todo':'done';t.updatedAt=new Date().toISOString();pCommit('Task completion updated');if(location.hash==='#start')renderStart();else route();}return;}
 let kind=a,record='',context={};if(a==='unit'){kind='unit';record=r;}else if(a==='checkin'){record=r;}else if(a.endsWith('-edit')){kind=a.slice(0,-5);record=r;}else if(a==='kr'){context.objectiveId=r;}else if(a.endsWith('-goal')){kind=a.slice(0,-5);context.objectiveId=r;}else if(a==='task-project'){kind='task';const i=state.initiatives.find(x=>x.id===r);context={projectId:r,objectiveId:i?.objectiveId,teamId:i?.teamId};}else if(a==='task-meeting'){kind='task';const m=state.meetings.find(x=>x.id===r);context={meetingId:r,objectiveId:m?.objectiveId,teamId:m?.teamId};}else if(a==='person-prefill'){kind='person';context.name=r;}else context.teamId=r&&r!=='all'?r:'company';pForm(kind,record,context);});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='platformMobile'){navigateSection('#'+el.value);return;}if(el.dataset.pFilter){pFilter[el.dataset.pFilter]=el.value;route();}});
let pSearchTimer;document.addEventListener('input',e=>{if(e.target.dataset.pFilter!=='q')return;const el=e.target,value=el.value,caret=el.selectionStart;clearTimeout(pSearchTimer);pSearchTimer=setTimeout(()=>{pFilter.q=value;route();const replacement=document.querySelector('[data-p-filter="q"]');replacement?.focus();replacement?.setSelectionRange?.(caret,caret);},220);});
