function pSourceInitiative(sid){const item=[...COMPANY_STRATEGY.initiatives,...COMPANY_STRATEGY.optionalBank].find(i=>i.id===sid);if(!item)return pMissing();const adopted=state.initiatives.find(i=>i.sourceId===sid);return pHead(item.title,txt('ابتکار مستند؛ برای شروع اجرا، مسئول و موعد را تعیین کنید.','Source initiative; assign an owner and due date before execution.'),adopted?pAnchor(txt('مشاهده پروژه اجرایی','Open execution project'),'#projects/'+adopted.id):pButton(txt('افزودن به برنامه','Add to plan'),'adopt-source',sid,true))+'<section class="p-card"><div class="p-actions">'+pUnitLink(item.unitId)+(item.objectiveId?pAnchor(pGoalTitle(pGoal(item.objectiveId)),'#goals/'+item.objectiveId,'p-link'):'')+(item.krId?pAnchor(txt('نتیجه کلیدی مرتبط','Related KR'),'#results/'+item.krId,'p-link'):'')+sourceLink(item.page)+'</div><p>'+esc(item.sourceUnit||'')+'</p>'+pTag(txt('ابتکار مندرج در سند؛ وضعیت اجرا تأیید نشده','Source initiative; execution not verified'),'source')+'</section>';}
const pBaseSetLanguage=setLanguage;setLanguage=function(lang){const hash=location.hash;pBaseSetLanguage(lang);const key=hash.slice(1).split('/')[0];if(pPages[key]||key==='start'){history.replaceState(history.state,'',hash);route();}};
